#!/usr/bin/env python3
"""常驻自动化统一心跳。

各进程周期性 beat(name)；巡检看 epoch，超时或进程不在就 kickstart。
落盘：~/Library/Application Support/youchu-agent-bus/state/hb/<name>.json
"""
from __future__ import annotations

import json
import os
import time
from pathlib import Path

HB_DIR = (
    Path.home()
    / "Library/Application Support/youchu-agent-bus/state/hb"
)


def _path(name: str) -> Path:
    safe = "".join(c if c.isalnum() or c in "-_." else "_" for c in name.strip())
    return HB_DIR / f"{safe}.json"


def beat(name: str, *, extra: dict | None = None) -> None:
    HB_DIR.mkdir(parents=True, exist_ok=True)
    payload = {
        "name": name,
        "epoch": int(time.time()),
        "pid": os.getpid(),
        "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    if extra:
        payload.update(extra)
    path = _path(name)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


def read(name: str) -> dict | None:
    path = _path(name)
    if not path.is_file():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None


def age_sec(name: str) -> int:
    data = read(name)
    if not data:
        return 10**9
    try:
        return max(0, int(time.time()) - int(data.get("epoch") or 0))
    except (TypeError, ValueError):
        return 10**9


def is_stale(name: str, max_age: int) -> bool:
    return age_sec(name) > max_age


def sleep_beating(name: str, seconds: float, *, every: float = 30.0) -> None:
    """可打断的长睡：边睡边写心跳。"""
    end = time.time() + max(0.0, float(seconds))
    every = max(5.0, float(every))
    while True:
        beat(name)
        remain = end - time.time()
        if remain <= 0:
            return
        time.sleep(min(every, remain))

