BY_ID = {s["id"]: s for s in SERVICES}


def _run(cmd: list[str], timeout: int = 120) -> tuple[int, str]:
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        out = ((p.stdout or "") + (p.stderr or "")).strip()
        return p.returncode, out[-4000:]
    except subprocess.TimeoutExpired:
        return 124, "timeout"
    except Exception as exc:
        return 1, str(exc)


def _pgrep(pat: str | None) -> list[str]:
    if not pat:
        return []
    rc, out = _run(["pgrep", "-fl", pat], timeout=5)
    if rc != 0:
        return []
    return [ln for ln in out.splitlines() if ln.strip()]


def _launch_info(label: str) -> dict:
    plist = HOME / "Library/LaunchAgents" / f"{label}.plist"
    info = {"plist": plist.is_file(), "loaded": False}
    if not info["plist"]:
        return info
    rc, out = _run(["launchctl", "print", f"gui/{UID}/{label}"], timeout=5)
    if rc != 0:
        return info
    info["loaded"] = True
    for line in out.splitlines():
        s = line.strip()
        if s.startswith("state ="):
            info["state"] = s.split("=", 1)[1].strip()
        if s.startswith("pid ="):
            try:
                info["pid"] = int(s.split("=", 1)[1].strip())
            except ValueError:
                pass
        if "last exit code" in s:
            info["last_exit"] = s.split("=", 1)[-1].strip()
        if s.startswith("runs ="):
            try:
                info["runs"] = int(s.split("=", 1)[1].strip())
            except ValueError:
                pass
    return info


def _hb(name: str | None) -> dict | None:
    if not name:
        return None
    p = STATE / "hb" / f"{name}.json"
    if not p.is_file():
        return None
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
        return {
            "age": max(0, int(time.time()) - int(d.get("epoch") or 0)),
            "pid": d.get("pid"),
            "ts": d.get("ts"),
        }
    except Exception:
        return None


def collect_status() -> dict:
    now = time.time()
    bot_hb = bus_hb = poller_age = vpn_age = None
    hp = Path("/tmp/tgbot-dc.heartbeat")
    if hp.is_file():
        try:
            d = json.loads(hp.read_text(encoding="utf-8"))
            bot_hb = int(now - int(d.get("bot") or 0))
            bus_hb = int(now - int(d.get("bus") or 0))
        except Exception:
            pass
    pp = STATE / "youchu_ai_poller.heartbeat"
    if pp.is_file():
        try:
            d = json.loads(pp.read_text(encoding="utf-8"))
            ep = int(d.get("epoch") or pp.stat().st_mtime)
            poller_age = int(now - ep)
        except Exception:
            pass
    vp = HOME / ".dc-platform/vpn/last_sync.json"
    if vp.is_file():
        try:
            d = json.loads(vp.read_text(encoding="utf-8"))
            imp = datetime.fromisoformat(d["imported_at"])
            vpn_age = round((datetime.now(timezone.utc) - imp).total_seconds() / 3600, 1)
        except Exception:
            pass

    rows = []
    for s in SERVICES:
        li = _launch_info(s["label"])
        procs = _pgrep(s.get("pattern"))
        alive = bool(procs)
        if s["kind"] == "keepalive":
            status = "RUNNING" if alive else ("LOADED" if li.get("loaded") else "MISSING")
        else:
            if not li.get("loaded"):
                status = "NOT_LOADED"
            elif li.get("state") == "running":
                status = "RUNNING_NOW"
            else:
                lex = str(li.get("last_exit", "0"))
                status = "OK" if lex in ("0", "(never exited)") else f"EXIT_{lex}"
        row = {
            **{k: s[k] for k in ("id", "name", "kind", "label", "note")},
            "status": status,
            "alive": alive,
            "proc": (procs[0][:120] if procs else ""),
            "launchd": li,
            "hb": _hb(s.get("hb")),
            "can_restart": bool(s.get("restart")),
            "can_trigger": bool(s.get("trigger")),
            "protect": bool(s.get("protect")),
        }
        if s["id"] == "tgbot":
            row["extra"] = f"bot_hb={bot_hb}s" if bot_hb is not None else ""
        elif s["id"] == "agent-bus-poller":
            row["extra"] = f"poller_hb={poller_age}s" if poller_age is not None else ""
        elif s["id"] == "vpn-sync":
            row["extra"] = f"上次同步 {vpn_age}h 前" if vpn_age is not None else ""
        else:
            row["extra"] = f"hb={row['hb']['age']}s" if row.get("hb") else ""
        rows.append(row)

    return {
        "generated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "bot_hb_age": bot_hb,
        "bus_hb_age": bus_hb,
        "poller_hb_age": poller_age,
        "vpn_age_h": vpn_age,
        "services": rows,
    }


def _log_action(action: str, sid: str, detail: str) -> None:
    STATE.mkdir(parents=True, exist_ok=True)
    line = f"[{datetime.now().strftime('%F %T')}] {action} {sid} {detail}\n"
    with ACTION_LOG.open("a", encoding="utf-8") as f:
        f.write(line)


def do_restart(sid: str) -> dict:
    s = BY_ID.get(sid)
    if not s or not s.get("restart"):
        return {"ok": False, "error": "不支持重启"}
    # 打卡子进程在跑时禁止重启调度（互不影响）
    if sid == "onehr" and _pgrep(r"onehr_checkin_auto\.py"):
        return {"ok": False, "error": "打卡子进程还在跑，禁止重启调度（互不影响）"}
    if s["restart"] == "tgbot-restart":
        rc, out = _run(["bash", str(ROOT / "omdb/tgbot/restart.sh")], timeout=90)
        _log_action("restart", sid, f"rc={rc}")
        return {"ok": rc == 0, "rc": rc, "output": out}
    if s["restart"] == "kick":
        rc, out = _run(
            ["launchctl", "kickstart", "-k", f"gui/{UID}/{s['label']}"],
            timeout=30,
        )
        _log_action("restart", sid, f"rc={rc}")
        return {"ok": rc == 0, "rc": rc, "output": out or "kickstart sent"}
    return {"ok": False, "error": "unknown restart"}


def do_trigger(sid: str) -> dict:
    s = BY_ID.get(sid)
    if not s or not s.get("trigger"):
        return {"ok": False, "error": "不支持触发"}
    t = s["trigger"]
    if t == "run-script":
        script = s.get("script")
        if not script or not Path(script).is_file():
            return {"ok": False, "error": f"脚本不存在: {script}"}
        # 后台跑，避免 HTTP 卡住
        subprocess.Popen(["bash", script], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        _log_action("trigger", sid, script)
        return {"ok": True, "output": f"已后台启动 {script}"}
    if t == "run-py":
        script = s.get("script")
        if not script or not Path(script).is_file():
            return {"ok": False, "error": f"脚本不存在: {script}"}
        py = "/usr/local/bin/python3"
        subprocess.Popen([py, "-u", script], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        _log_action("trigger", sid, script)
        return {"ok": True, "output": f"已后台启动 {script}"}
    if t == "kick-once":
        rc, out = _run(["launchctl", "kickstart", f"gui/{UID}/{s['label']}"], timeout=30)
        _log_action("trigger", sid, f"kickstart rc={rc}")
        return {"ok": rc == 0, "rc": rc, "output": out or "kickstart sent"}
    if t == "vpn-force":
        py = Path.home() / ".dc-platform/scripts/vpn_ovpn_sync.py"
        if not py.is_file():
            return {"ok": False, "error": "缺少 vpn_ovpn_sync.py"}
        bin_py = "/usr/local/bin/python3"
        subprocess.Popen(
            [bin_py, "-u", str(py), "--force-request"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        _log_action("trigger", sid, "vpn --force-request")
        return {"ok": True, "output": "已后台强制续期 VPN"}
    if t == "onehr-sync":
        env = HOME / ".dc-platform/config/onehr.env"
        auto = HOME / ".dc-platform/scripts/onehr_checkin_auto.py"
        subprocess.Popen(
            ["/usr/local/bin/python3", "-u", str(auto), "--env", str(env), "--sync-schedule"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        _log_action("trigger", sid, "onehr --sync-schedule")
        return {"ok": True, "output": "已后台同步人效通今日状态"}
    return {"ok": False, "error": "unknown trigger"}


